/* Versioned rich descriptions; legacy descriptions remain plain text. */
window.TicketRichText=(()=>{
 const prefix='<!--project-rich-text:v1-->';
 const allowed=new Set(['P','DIV','BR','STRONG','B','EM','I','U','S','STRIKE','H2','H3','UL','OL','LI','BLOCKQUOTE','PRE','CODE','A']);
 function sanitize(html){const doc=new DOMParser().parseFromString(html,'text/html'),out=document.createElement('div');function copy(node,parent){if(node.nodeType===3){parent.append(document.createTextNode(node.textContent));return}if(node.nodeType!==1)return;if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH'].includes(node.tagName))return;if(!allowed.has(node.tagName)){for(const child of node.childNodes)copy(child,parent);return}const el=document.createElement(node.tagName.toLowerCase());if(node.tagName==='A'){const href=node.getAttribute('href')||'';if(/^(https?:\/\/|mailto:)/i.test(href)){el.setAttribute('href',href);el.setAttribute('rel','noopener noreferrer')}}for(const child of node.childNodes)copy(child,el);parent.append(el)}for(const child of doc.body.childNodes)copy(child,out);return out.innerHTML}
 function html(value){if(value.startsWith(prefix))return sanitize(value.slice(prefix.length));const el=document.createElement('div');el.textContent=value;return el.innerHTML.replaceAll('\n','<br>')}
 function mount(textarea){if(textarea._rich){textarea._rich.remove();}const box=document.createElement('div');box.className='ticket-rich';box.innerHTML='<div class="rich-toolbar" role="toolbar" aria-label="Description formatting"></div><div class="rich-body" contenteditable="true" role="textbox" aria-label="Ticket description" aria-multiline="true"></div><div class="rich-count"></div>';textarea.after(box);textarea.hidden=true;textarea._rich=box;const body=box.querySelector('.rich-body'),toolbar=box.firstElementChild;body.innerHTML=html(textarea.value||'');let range;
 function count(){box.querySelector('.rich-count').textContent=(body.textContent.trim().match(/\S+/g)||[]).length+' words'}
 function sync(){textarea.value=prefix+sanitize(body.innerHTML);textarea.dispatchEvent(new Event('input',{bubbles:true}));count()}
 const buttons=[['Paragraph','formatBlock','p'],['Heading','formatBlock','h2'],['Bold','bold'],['Italic','italic'],['Underline','underline'],['Strike','strikeThrough'],['Bullets','insertUnorderedList'],['Numbered list','insertOrderedList'],['Quote','formatBlock','blockquote'],['Code','formatBlock','pre'],['Link','createLink'],['Undo','undo'],['Redo','redo']];
 for(const [label,command,value] of buttons){const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-label',label);b.onmousedown=e=>e.preventDefault();b.onclick=()=>{body.focus();if(range){const s=getSelection();s.removeAllRanges();s.addRange(range)}let arg=value;if(command==='createLink'){arg=prompt('Link URL (https:// or mailto:)');if(!arg)return;if(!/^(https?:\/\/|mailto:)/i.test(arg)){alert('Use an http, https or mailto link.');return}}document.execCommand(command,false,arg);sync()};toolbar.append(b)}
 function remember(){const s=getSelection();if(s.rangeCount&&body.contains(s.anchorNode))range=s.getRangeAt(0).cloneRange()}
 body.onkeyup=remember;body.onmouseup=remember;body.oninput=()=>{sync();remember()};body.onpaste=e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));sync()};body.ondrop=e=>e.preventDefault();count();return box;
 }
 return {mount,sanitize,html,prefix};
})();
